// Generated by Cypress Author on 2026-10-19
//
// REN 03 · REN 06 (P0) — Plano_de_Testes_QA_MatchWallet.md §7.
// Fórmulas (acumulado capitalizado, % do CDI) pertencem ao backend; aqui validamos o que a tela
// controla: validação do formulário, prévia sem NaN/Infinity, payload numérico e o aviso de
// acumulado divergente devolvido pela API.
//
// Observação para o QA: o formulário rejeita CDI = 0 e CDI vazio com a MESMA mensagem
// ("O CDI deve ser maior que zero"). O plano pede distinguir ausência de zero (REN 03).

const CARTEIRA_ID = 'cart-1'

const DETALHE = {
  id: CARTEIRA_ID,
  nome: 'Carteira Moderada',
  perfilAlvo: 'MODERADO',
  descricao: null,
  ativa: true,
  criadoEm: '2026-01-01T00:00:00.000Z',
  versaoAtual: null,
}

const HISTORICO = {
  carteiraId: CARTEIRA_ID,
  carteiraNome: 'Carteira Moderada',
  serie: [
    { mesReferencia: '2026-08', rentabilidade: 2, cdi: 1, ibov: 0.5, percentualCdi: 200 },
    { mesReferencia: '2026-09', rentabilidade: -1, cdi: 0, ibov: -3, percentualCdi: null },
  ],
  acumulado: { carteira: 0.98, cdi: 1, ibov: -2.5 },
}

function preencher(campos: {
  competencia: string
  carteira: string
  acumulado: string
  cdi: string
  ibov: string
}) {
  cy.get('[data-cy="rentab-competencia"]').type(campos.competencia)
  cy.get('[data-cy="rentab-carteira"]').type(campos.carteira)
  cy.get('[data-cy="rentab-acumulado"]').type(campos.acumulado)
  if (campos.cdi) {
    cy.get('[data-cy="rentab-cdi"]').type(campos.cdi)
  }
  cy.get('[data-cy="rentab-ibov"]').type(campos.ibov)
}

describe('Plano QA · Rentabilidade (admin)', () => {
  beforeEach(() => {
    cy.bloquearApi()
    cy.stubSessao('admin')
    cy.stubApi('GET', `/carteiras/${CARTEIRA_ID}`, DETALHE, 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${CARTEIRA_ID}/versoes*`,
      { items: [], total: 0, page: 1, pageSize: 100 },
      'versoes',
    )
    cy.stubApi('GET', `/carteiras/${CARTEIRA_ID}/historico-performance*`, HISTORICO, 'historico')
    cy.stubApi(
      'POST',
      `/carteiras/${CARTEIRA_ID}/rentabilidade`,
      { statusCode: 201, body: {} },
      'lancar',
    )

    cy.visit(`/admin/carteiras/${CARTEIRA_ID}`)
    cy.wait(['@detalhe', '@versoes'])
    cy.contains('[role="tab"]', 'Rentabilidade').click()
    cy.wait('@historico')
  })

  it('REN 06 · histórico com meses +2% e -1% e CDI zero → mostra cada linha sem NaN/Infinity e "—" no % do CDI indefinido', () => {
    cy.get('[data-cy="rentab-linha"]').should('have.length', 2)
    cy.get('[data-cy="rentab-linha"]')
      .eq(0)
      .should('contain.text', '2,00')
      .and('contain.text', '200')
    // CDI = 0 no mês: o backend manda percentualCdi nulo e a tela mostra traço, nunca Infinity.
    cy.get('[data-cy="rentab-linha"]').eq(1).should('contain.text', '1,00').and('contain.text', '—')
    cy.get('body')
      .invoke('text')
      .should('not.match', /NaN|Infinity/)
  })

  it('REN 03 · CDI 0 ou vazio → bloqueia o envio com a mensagem de validação e prévia sem divisão por zero', () => {
    cy.get('[data-cy="rentab-lancar"]').click()
    preencher({ competencia: '2026-10', carteira: '1.5', acumulado: '6.25', cdi: '0', ibov: '-2' })
    cy.get('[data-cy="rentab-previa"]').should('have.text', '—')
    cy.get('[data-cy="rentab-submit"]').click()

    cy.contains('O CDI deve ser maior que zero').should('be.visible')
    cy.get('@lancar.all').should('have.length', 0)

    // CDI vazio: mesma barreira (ver observação no topo do arquivo).
    cy.get('[data-cy="rentab-cdi"]').clear()
    cy.get('[data-cy="rentab-submit"]').click()
    cy.contains('O CDI deve ser maior que zero').should('be.visible')
    cy.get('@lancar.all').should('have.length', 0)
    cy.get('body')
      .invoke('text')
      .should('not.match', /NaN|Infinity/)
  })

  it('REN 06 · lançamento com acumulado divergente → envia números e exibe o acumulado calculado pela API', () => {
    cy.stubApi(
      'POST',
      `/carteiras/${CARTEIRA_ID}/rentabilidade`,
      { statusCode: 201, body: { avisos: ['ACUMULADO_DIVERGENTE'], acumuladoCalculado: 0.98 } },
      'lancar',
    )

    cy.get('[data-cy="rentab-lancar"]').click()
    preencher({ competencia: '2026-10', carteira: '1.5', acumulado: '6.25', cdi: '1', ibov: '-2' })
    // Prévia = carteira ÷ CDI × 100 = 150 %.
    cy.get('[data-cy="rentab-previa"]').should('contain.text', '150')
    cy.get('[data-cy="rentab-submit"]').click()

    cy.wait('@lancar').its('request.body').should('deep.equal', {
      mesReferencia: '2026-10',
      rentabilidadeMes: 1.5,
      rentabilidadeAcumuladaAno: 6.25,
      cdiMes: 1,
      ibovMes: -2,
    })
    cy.contains('Rentabilidade de 2026-10 lançada').should('be.visible')
    cy.contains('diverge do calculado').should('contain.text', '0,98')
  })
})

export {}
